body.script:
(function () {
  var wrap = document.querySelector('.wrap'), T = wrap.getAttribute('data-t'), C = wrap.getAttribute('data-c');
  function send(box, status, note, btn) {
    var fd = new FormData();
    fd.append('csrf_token', C); fd.append('x_name', 'report'); fd.append('x_token', T);
    fd.append('x_stop', box.getAttribute('data-stop')); fd.append('x_status', status); fd.append('x_note', note || '');
    var cash = [];
    if (status === 'delivered') { Array.prototype.forEach.call(box.querySelectorAll('.cash input'), function (i) { cash.push(i.getAttribute('data-sale') + '=' + (parseFloat(i.value) || 0)); }); }
    fd.append('x_cash', cash.join(','));
    btn.disabled = true; box.querySelector('.err').hidden = true;
    fetch('/website/form/x_delivery_report', { method: 'POST', body: fd })
      .then(function (r) { return r.json(); })
      .then(function (j) { if (!j || !j.id) { throw new Error('no id'); } location.hash = 's' + box.getAttribute('data-stop'); location.reload(); })
      .catch(function () { btn.disabled = false; box.querySelector('.err').hidden = false; });
  }
  document.addEventListener('click', function (e) {
    var hb = e.target.closest ? e.target.closest('.ho .b') : null; if (!hb) { return; }
    var box = hb.closest('.ho'), fd = new FormData();
    fd.append('csrf_token', C); fd.append('x_name', 'cash'); fd.append('x_token', T); fd.append('x_stop', '0'); fd.append('x_handover', hb.getAttribute('data-h'));
    hb.disabled = true; box.querySelector('.err').hidden = true;
    fetch('/website/form/x_delivery_report', { method: 'POST', body: fd })
      .then(function (r) { return r.json(); })
      .then(function (j) { if (!j || !j.id) { throw new Error('no id'); } location.hash = 'ho'; location.reload(); })
      .catch(function () { hb.disabled = false; box.querySelector('.err').hidden = false; });
  });
  /* a tap by mistake must not report a stop: every report is confirmed in a pop-up first (owner, 25 Nov 2026) */
  var ask = document.getElementById('ask'), pending = null;
  function confirmFirst(box, status, note, btn) {
    var stop = box.closest('.stop'), title = stop.querySelector('.t').textContent, ok = status === 'delivered', lines = [title], cash = [];
    if (ok) { Array.prototype.forEach.call(box.querySelectorAll('.cash input'), function (i) { cash.push('$' + (parseFloat(i.value) || 0).toFixed(2)); }); }
    if (cash.length) { lines.push('Cash received: ' + cash.join(' + ')); }
    if (!ok) { lines.push(note ? 'Reason: ' + note : 'No reason written'); }
    var q = document.getElementById('askq'), y = document.getElementById('asky');
    q.textContent = 'Stop ' + box.getAttribute('data-stop') + ': ' + (ok ? 'delivered?' : 'NOT delivered?'); q.className = 'askq ' + (ok ? '' : 'no');
    document.getElementById('askd').textContent = lines.join(' · ');
    y.textContent = ok ? 'Yes, delivered' : 'Yes, not delivered'; y.className = 'b on ' + (ok ? 'ok' : 'no');
    pending = function () { send(box, status, note, btn); }; ask.hidden = false;
  }
  document.getElementById('askn').addEventListener('click', function () { pending = null; ask.hidden = true; });
  document.getElementById('asky').addEventListener('click', function () { var go = pending; pending = null; ask.hidden = true; if (go) { go(); } });
  /* "Return?": photos are shrunk in the phone (longest side 1600 px, JPEG) before they are sent, at most three */
  function shrink(file) { return new Promise(function (res) { var img = new Image();
    img.onload = function () { var k = Math.min(1, 1600 / Math.max(img.width, img.height)), c = document.createElement('canvas'); c.width = Math.round(img.width * k); c.height = Math.round(img.height * k);
      c.getContext('2d').drawImage(img, 0, 0, c.width, c.height); c.toBlob(function (b) { URL.revokeObjectURL(img.src); res(b || file); }, 'image/jpeg', 0.8); };
    img.onerror = function () { res(file); }; img.src = URL.createObjectURL(file); }); }
  document.addEventListener('click', function (e) {
    var l = e.target.closest ? e.target.closest('.retl') : null;
    if (l) { e.preventDefault(); var bx = l.parentNode.querySelector('.retb'); bx.hidden = !bx.hidden; return; }
    var sb = e.target.closest ? e.target.closest('.rets') : null; if (!sb) { return; }
    var box = sb.closest('.ret'), files = Array.prototype.slice.call(box.querySelector('.retf').files || [], 0, 3), err = box.querySelector('.err'), wait = box.querySelector('.retw');
    if (!files.length) { err.textContent = 'Choose or take a photo first.'; err.hidden = false; return; }
    sb.disabled = true; err.hidden = true; wait.hidden = false;
    Promise.all(files.map(shrink)).then(function (blobs) {
      var fd = new FormData(), sel = box.querySelector('.retp');
      fd.append('csrf_token', C); fd.append('x_name', 'return'); fd.append('x_token', T); fd.append('x_stop', box.getAttribute('data-stop'));
      fd.append('x_note', box.querySelector('.retx').value.trim()); fd.append('x_partner', sel ? sel.value : '0');
      blobs.forEach(function (b, i) { fd.append('x_photo' + (i + 1), b, 'return-' + (i + 1) + '.jpg'); });
      return fetch('/website/form/x_delivery_report', { method: 'POST', body: fd }); })
      .then(function (r) { return r.json(); })
      .then(function (j) { if (!j || !j.id) { throw new Error('no id'); } location.hash = 's' + box.getAttribute('data-stop'); location.reload(); })
      .catch(function () { sb.disabled = false; wait.hidden = true; err.textContent = 'Not sent. Check the connection and try again.'; err.hidden = false; });
  });
  document.addEventListener('click', function (e) {
    var btn = e.target.closest ? e.target.closest('.rep .b') : null; if (!btn) { return; }
    var box = btn.closest('.rep'), s = btn.getAttribute('data-s');
    if (s === 'delivered') { confirmFirst(box, 'delivered', '', btn); }
    else if (s === 'failed') { box.querySelector('.why').hidden = false; box.querySelector('.why input').focus(); }
    else if (s === 'send') { confirmFirst(box, 'failed', box.querySelector('.why input').value.trim(), btn); }
  });
})();
